const tabId = 825319279;
await tool.navigate({ tabId, url: "https://www.citationmachine.net/" });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });

const details = await browserjs(tabId, () => {
  // Let's find all text containing "Harvard"
  const allElements = Array.from(document.querySelectorAll('*'));
  const harvardElements = allElements.filter(el => {
    return el.children.length === 0 && el.textContent.includes('Harvard');
  }).map(el => ({
    tagName: el.tagName,
    text: el.textContent.trim(),
    parentClass: el.parentElement?.className,
    parentText: el.parentElement?.innerText?.slice(0, 100)
  }));

  return {
    harvardElements
  };
});
console.log(details);

