const tabId = 825319264;
const query = "cybersecurity basics for students middle school online safety";
await tool.navigate({ tabId, url: `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}` });
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 6000 });

const videoList = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll('ytd-video-renderer, #video-title')).map(el => {
    const a = el.tagName === 'A' ? el : el.querySelector('a#video-title');
    const channel = el.querySelector('#channel-info, #channel-name, .ytd-channel-name')?.textContent?.trim();
    return {
      title: a?.title || a?.textContent?.trim(),
      href: a?.href,
      channel: channel
    };
  }).filter(item => item.title && item.href && item.href.includes('/watch'));

  // Deduplicate by href
  const seen = new Set();
  const deduped = [];
  for (const item of items) {
    if (!seen.has(item.href)) {
      seen.add(item.href);
      deduped.push(item);
    }
  }
  return deduped.slice(0, 10);
});
console.log("YouTube videos found:", videoList);

