const tabId = 825319280;

// Check video element and play it
const videoStatus = await browserjs(tabId, async () => {
  const video = document.querySelector('video');
  if (!video) return { error: "no video element" };

  // Unmute if muted, set volume
  video.muted = false;

  // Play
  try {
    await video.play();
  } catch (e) {
    // If autoplay policy blocks unmuted play, play muted
    video.muted = true;
    await video.play();
  }

  return {
    paused: video.paused,
    currentTime: video.currentTime,
    duration: video.duration,
    muted: video.muted
  };
});
console.log("Video status before wait:", videoStatus);

// Let it play for a few seconds
await new Promise(r => setTimeout(r, 4000));

// Check status, transcript / captions or description
const playbackInfo = await browserjs(tabId, () => {
  const video = document.querySelector('video');
  const subtitles = Array.from(document.querySelectorAll('.ytp-caption-segment')).map(s => s.textContent).join(' ');

  return {
    currentTime: video?.currentTime,
    paused: video?.paused,
    subtitles
  };
});
console.log("Playback info after 4s:", playbackInfo);

