const tabId = 825319280;

// Let's get the full transcript or caption text from 0 to 30 seconds
const transcript = await browserjs(tabId, async () => {
  // Let's click the description "more" or transcript button if available
  const moreBtn = document.querySelector('#expand, #description-inline-expander #expand');
  if (moreBtn) moreBtn.click();

  // Wait a bit
  await new Promise(r => setTimeout(r, 500));

  // Try to find "Show transcript" button
  const transcriptBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Show transcript') || b.getAttribute('aria-label')?.includes('Show transcript'));
  if (transcriptBtn) {
    transcriptBtn.click();
    await new Promise(r => setTimeout(r, 1000));
  }

  const segments = Array.from(document.querySelectorAll('ytd-transcript-segment-renderer')).map(s => ({
    time: s.querySelector('.segment-timestamp')?.textContent?.trim(),
    text: s.querySelector('.segment-text')?.textContent?.trim()
  }));

  return { segments: segments.slice(0, 10) };
});
console.log("Transcript segments:", transcript);

